#!/usr/bin/env node
/**
 * AI Sandbox HTTP wrapper for the Test 7 batch runner.
 *
 * Listens on port 3000 (ALB requirement) and satisfies the health check at
 * GET / while providing a simple API to trigger and monitor batch runs.
 *
 * Routes:
 *   GET  /        — HTML status page; always returns 200 (ALB health check)
 *   GET  /status  — JSON run state
 *   GET  /logs    — plain-text log tail  (?n=N lines, default 100)
 *   POST /run     — start a run; body is JSON with optional overrides:
 *                     { models, scenarios, defences, reps,
 *                       s3Bucket, s3Prefix, s3Region, awsRegion, runId }
 *                   Returns 202 if accepted, 409 if a run is already in progress.
 */

import http from "http";
import { spawn } from "child_process";
import { readFileSync, readdirSync, statSync } from "fs";
import path from "path";

const PORT = 3000;
const MAX_LOG_LINES = 20000;
const ENTRYPOINTS = {
  "1": "/docker-entrypoint-test1.sh",
  "3": "/docker-entrypoint-test3.sh",
  "3a": "/docker-entrypoint-test3a.sh",
  "4": "/docker-entrypoint-test4.sh",
  "7": "/docker-entrypoint.sh",
  "8": "/docker-entrypoint-test8.sh",
  "9": "/docker-entrypoint-test9.sh",
  "9a": "/docker-entrypoint-test9a.sh",
  "8b6": "/docker-entrypoint-test8b6.sh",
  "10": "/docker-entrypoint-test10.sh",
  "12": "/docker-entrypoint-test12.sh",
  "12a": "/docker-entrypoint-test12a.sh",
  "12b": "/docker-entrypoint-test12b.sh",
  "12c": "/docker-entrypoint-test12c.sh",
  "13": "/docker-entrypoint-test13.sh",
  "14": "/docker-entrypoint-test14.sh",
  "15": "/docker-entrypoint-test15.sh",
  "16": "/docker-entrypoint-test16.sh",
  "17": "/docker-entrypoint-test17.sh",
  "18": "/docker-entrypoint-test18.sh",
  "20": "/docker-entrypoint-test20.sh",
  "21": "/docker-entrypoint-test21.sh",
  "22": "/docker-entrypoint-test22.sh",
  "23": "/docker-entrypoint-test23.sh",
  "24": "/docker-entrypoint-test24.sh",
  "25": "/docker-entrypoint-test25.sh",
  "26": "/docker-entrypoint-test26.sh",
  "27": "/docker-entrypoint-test27.sh",
  "29": "/docker-entrypoint-test29.sh",
  "promptarmor-bedrock": "/docker-entrypoint-promptarmor-bedrock.sh",
  "injecagent": "/docker-entrypoint-injecagent.sh",
  "mt-agentrisk": "/docker-entrypoint-mt-agentrisk.sh",
  "test-framework": "/docker-entrypoint-test-framework.sh",
  "agentlab": "/docker-entrypoint-agentlab.sh",
  "mode4": "/docker-entrypoint-mode4.sh",
  "t3e": "/docker-entrypoint-t3e.sh",
  "t5": "/docker-entrypoint-t5.sh",
};
const DEFAULT_TEST = process.env.TEST_NUM || "7";
const BUILD_VERSION = JSON.parse(readFileSync(new URL("./package.json", import.meta.url), "utf8")).version;

// ---------------------------------------------------------------------------
// Run state
// ---------------------------------------------------------------------------

const INITIAL_PROGRESS = {
  totalCombinations: 0,
  completedCombinations: 0,
  failedCombinations: 0,
  completedRuns: 0,       // individual repetitions
  lastGES: null,
};

let state = {
  status: "idle",   // idle | running | done | failed
  runId: null,
  params: null,
  startedAt: null,
  finishedAt: null,
  exitCode: null,
  pid: null,
  logLines: [],
  progress: { ...INITIAL_PROGRESS },
};

let currentProcess = null;

function appendLog(line) {
  state.logLines.push(line);
  if (state.logLines.length > MAX_LOG_LINES) state.logLines.shift();
  process.stdout.write(line + "\n");

  // Track progress from log output
  // Total combinations: "[1/12]" pattern from entrypoint or ">>> N combinations queued"
  const totalMatch = line.match(/\[\d+\/(\d+)\]/);
  if (totalMatch) state.progress.totalCombinations = parseInt(totalMatch[1], 10);
  const queuedMatch = line.match(/>>> (\d+) combinations queued/);
  if (queuedMatch) state.progress.totalCombinations = parseInt(queuedMatch[1], 10);

  // Combination completed (Test 7: "Completed in", Test 3: "DONE in")
  if (/Completed in \d+s/.test(line) || /\] DONE in \d+s/.test(line)) {
    state.progress.completedCombinations++;
  }
  // Combination failed
  if (/WARNING: run failed/.test(line) || /\] FAILED:/.test(line)) {
    state.progress.completedCombinations++;
    state.progress.failedCombinations++;
  }

  // Individual test result (one per repetition)
  if (/^RESULT:/.test(line) || /^\s+RESULT:/.test(line)) {
    state.progress.completedRuns++;
  }
  // Extract GES from result blocks
  const gesMatch = line.match(/GES:\s+([\d.]+)/);
  if (gesMatch) state.progress.lastGES = parseFloat(gesMatch[1]);
}

function startRun(params) {
  const env = Object.assign({}, process.env);
  const testNum = String(params.test || DEFAULT_TEST);
  const entrypoint = ENTRYPOINTS[testNum];
  if (!entrypoint) {
    throw new Error(`Unknown test number: ${testNum}. Valid: ${Object.keys(ENTRYPOINTS).join(", ")}`);
  }

  // Test 7 env vars
  if (params.models)    env.TEST7_MODELS    = String(params.models);
  if (params.scenarios) env.TEST7_SCENARIOS = String(params.scenarios);
  if (params.defences)  env.TEST7_DEFENCES  = String(params.defences);
  if (params.reps)      env.TEST7_REPS      = String(params.reps);
  if (params.effort)    env.TEST7_EFFORT    = String(params.effort);
  if (params.runId)     env.TEST7_RUN_ID    = String(params.runId);

  // Test 3 env vars
  if (params.models)    env.TEST3_MODELS    = String(params.models);
  if (params.scenarios) env.TEST3_SCENARIOS = String(params.scenarios);
  if (params.defences)  env.TEST3_DEFENCES  = String(params.defences);
  if (params.parallel)  env.PARALLEL_JOBS   = String(params.parallel);
  if (params.runId)     env.TEST3_RUN_ID    = String(params.runId);

  // Test 1 env vars
  if (params.effort)    env.TEST1_EFFORT    = String(params.effort);
  if (params.config)    env.TEST1_CONFIG    = String(params.config);

  // Test 3a env vars
  if (params.efforts)   env.TEST3A_EFFORTS  = String(params.efforts);
  if (params.reps)      env.TEST3A_REPS     = String(params.reps);
  if (params.runId)     env.TEST3A_RUN_ID   = String(params.runId);

  // Test 9a env vars
  if (params.matrix)    env.TEST9A_MATRIX   = String(params.matrix);
  if (params.reps)      env.TEST9A_REPS     = String(params.reps);
  if (params.runId)     env.TEST9A_RUN_ID   = String(params.runId);

  // Test 8 env vars
  if (params.effort)    env.TEST8_EFFORT    = String(params.effort);
  if (params.reps)      env.TEST8_REPS      = String(params.reps);
  if (params.models)    env.TEST8_MODELS    = String(params.models);
  if (params.hardened)  env.TEST8_HARDENED   = "true";
  if (params.prompt)    env.TEST8_PROMPT     = String(params.prompt);
  if (params.b6)        env.TEST8_B6         = "true";

  // Test 8 B6 env vars
  if (params.effort)    env.TEST8B6_EFFORT  = String(params.effort);
  if (params.reps)      env.TEST8B6_REPS    = String(params.reps);
  if (params.models)    env.TEST8B6_MODELS  = String(params.models);

  // Test 10/11 env vars
  if (params.defences)      env.TEST10_DEFENCES     = String(params.defences);
  if (params.model)         env.TEST10_MODEL        = String(params.model);
  if (params.effort)        env.TEST10_EFFORT       = String(params.effort);
  if (params.judgeEffort)   env.TEST10_JUDGE_EFFORT = String(params.judgeEffort);
  if (params.reps)          env.TEST10_REPS         = String(params.reps);

  // Test 15 env vars (FPR under prompt v2)
  if (params.prompt)    env.TEST15_PROMPT   = String(params.prompt);
  if (params.task)      env.TEST15_TASK     = String(params.task);
  if (params.reps)      env.TEST15_REPS     = String(params.reps);
  if (params.model)     env.TEST15_MODEL    = String(params.model);

  // Test 25 env vars (AgentLAB)
  if (params.models)     env.TEST25_MODELS       = String(params.models);
  if (params.defences)   env.TEST25_DEFENCES     = String(params.defences);
  if (params.scenarios)  env.TEST25_SCENARIOS    = String(params.scenarios);
  if (params.attackTypes) env.TEST25_ATTACK_TYPES = String(params.attackTypes);
  if (params.seed)       env.TEST25_SEED         = String(params.seed);
  if (params.maxTurns)   env.TEST25_MAX_TURNS    = String(params.maxTurns);
  if (params.backend)    env.TEST25_BACKEND      = String(params.backend);
  if (params.runId)      env.TEST25_RUN_ID       = String(params.runId);

  // Mode 4 env vars (Paper14 §VII behavioural drift). Most callers will
  // pass these through `params.env`; these convenience mappings mirror the
  // entrypoint's env contract for the common knobs.
  if (params.models)     env.AGENT_MODELS = String(params.models);
  if (params.configs)    env.CONFIGS      = String(params.configs);
  if (params.floodTurns) env.FLOOD_TURNS  = String(params.floodTurns);
  if (params.reps)       env.REPETITIONS  = String(params.reps);
  if (params.rcThreshold) env.RC_THRESHOLD = String(params.rcThreshold);
  if (params.concurrency) env.RUNNER_CONCURRENCY = String(params.concurrency);
  if (params.runId)      env.RUN_ID       = String(params.runId);

  // Generic env passthrough (test 12 / AgentDojo uses this)
  if (params.env && typeof params.env === "object") {
    for (const [k, v] of Object.entries(params.env)) {
      env[k] = String(v);
    }
  }

  // Shared env vars
  if (params.s3Bucket)  env.S3_BUCKET       = String(params.s3Bucket);
  if (params.s3Prefix)  env.S3_PREFIX       = String(params.s3Prefix);
  if (params.s3Region)  env.S3_REGION       = String(params.s3Region);
  if (params.awsRegion) env.AWS_REGION      = String(params.awsRegion);
  if (params.bedrockRegion) env.BEDROCK_REGION = String(params.bedrockRegion);

  const runId = env.TEST7_RUN_ID || env.TEST3_RUN_ID || new Date().toISOString().replace(/[:.]/g, "");

  state = {
    status: "running",
    runId,
    params,
    startedAt: new Date().toISOString(),
    finishedAt: null,
    exitCode: null,
    pid: null,
    logLines: [],
    progress: { ...INITIAL_PROGRESS },
  };

  const child = spawn(entrypoint, [], {
    env,
    stdio: ["ignore", "pipe", "pipe"],
  });

  state.pid = child.pid;
  currentProcess = child;

  child

/**
 * Judge AI Dredd — shared server plumbing.
 *
 * This module holds everything both the hook container and the dashboard
 * container need at startup: CLI argument parsing, the console→file log
 * mirror, store/interceptor construction, request-body size caps,
 * session-id validation, path validation, hook-auth middleware, transcript
 * backfill, and the session-log shape builder used by the dashboard.
 *
 * Neither `server-hook.ts` nor `server-dashboard.ts` instantiates stores
 * directly — they import `tracker`, `apiKeys`, `interceptor` from here. The
 * dashboard container constructs all three too, even though it doesn't
 * call `interceptor.evaluate`, because the sessions listing reads
 * `interceptor.getLog()` for its per-session rendering.
 *
 * All module-level side effects (logger wiring, `[STORE]` / `[AUTH]`
 * startup prints) happen here exactly once per process.
 */

import { type IncomingMessage, type ServerResponse } from "node:http";
import { randomUUID } from "node:crypto";
import { parseArgs } from "node:util";
import {
  appendFileSync,
  createWriteStream,
  existsSync,
  mkdirSync,
  readFileSync,
  realpathSync,
  renameSync,
  statSync,
} from "node:fs";
import { join, sep } from "node:path";
import { inspect } from "node:util";

// ============================================================================
// .env.local loader (local dev only)
// ============================================================================
//
// On the sandbox/Fargate deployment, secrets come from SSM via the task
// definition's `secrets` map — the env vars are already populated when this
// process starts. For local development we'd rather not require `export
// CLERK_SECRET_KEY=…` before every `npm run server`, so this block looks
// for `.env.local` in the project root and parses it into process.env.
//
// Behaviour:
//   - File missing → silent no-op.
//   - Key already set in process.env → not overwritten. The shell's
//     environment always wins so a one-off override stays a one-off.
//   - Lines starting with # are comments. Empty lines are skipped.
//   - Values may be quoted with single or double quotes; quotes are
//     stripped. No interpolation, no `export` prefix support — keep it
//     simple. If the format isn't enough, source the file from your
//     shell instead.
//
// `.env.local` is gitignored. NEVER commit secrets.
(() => {
  // Resolve relative to this source file so it works whether run from the
  // repo root or a different cwd (e.g. tsx invoked from /tmp).
  const candidates = [
    new URL("../.env.local", import.meta.url),
    new URL("../../.env.local", import.meta.url),
  ];
  for (const url of candidates) {
    let raw: string;
    try {
      raw = readFileSync(url, "utf8");
    } catch {
      continue;
    }
    for (const line of raw.split(/\r?\n/)) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith("#")) continue;
      const eq = trimmed.indexOf("=");
      if (eq < 0) continue;
      const key = trimmed.slice(0, eq).trim();
      let value = trimmed.slice(eq + 1).trim();
      if (
        (value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))
      ) {
        value = value.slice(1, -1);
      }
      if (key && process.env[key] === undefined) {
        process.env[key] = value;
      }
    }
    break;
  }
})();
import { InMemorySessionStore } from "./session-tracker.js";
import { DynamoSessionStore } from "./dynamo-session-store.js";
import { CachedSessionStore } from "./cached-session-store.js";
import type { SessionStore, ImageBlock, IntentEntry } from "./session-store.js";
import { MAX_ACTIVE_INTENTS, RESOLVED_INTENT_TTL_MS } from "./session-tracker.js";
import { embedAny, cosineSimilarity } from "./ollama-client.js";
import {
  type ApiKeyStore,
  InMemoryApiKeyStore,
} from "./api-key-store.js";
import { DynamoApiKeyStore } from "./dynamo-api-key-store.js";
import { CachedApiKeyStore } from "./cached-api-key-store.js";
import {
  type ApprovalStore,
  InMemoryApprovalStore,
} from "./approval-store.js";
import { DynamoApprovalStore } from "./dynamo-approval-store.js";
import { CachedApprovalStore } from "./cached-approval-store.js";
import {
  type UserPermissionsStore,
  InMemoryUserPermissionsStore,
} from "./user-permissions-store.js";
import { DynamoUserPermissionsStore } from "./dynamo-user-permissions-store.js";
import { pruneExpiredPendingApprovals } from "./pending-approvals.js";
import { PreToolInterceptor } from "./pretool-interceptor.js";
import type { PromptVariant } from "./intent-judge.js";

export type TrustMode = "interactive" | "autonomous" | "learn";

// ============================================================================
// CLI parsing + CONFIG
// ============================================================================

const { values } = parseArgs({
  options: {
    port: { type: "string", default: "3001" },
    mode: { type: "string", default: "autonomous" },
    "judge-model": { type: "string", default: "nemotron-3-super" },
    backend: { type: "string", default: "ollama" },
    "embedding-model": { type: "string", default: "eu.cohere.embed-v4:0" },
    "hardened": { type: "boolean", default: false },
    "prompt": { type: "string", default: "" },
    "judge-effort": { type: "string", default: "" },
    "review-threshold": { type: "string", default: "0.6" },
    "deny-threshold": { type: "string", default: "0.15" },
    "hijack-threshold": { type: "string", default: "2" },
    "log-dir": { type: "string", default: "./results" },
    "console-log-dir": { type: "string", default: "./logs" },
  },
});

// File logger — mirrors all console output to dredd-YYYY-MM-DD.log.
//
// Why this isn't appendFileSync: every console.* call would block the
// Node event loop while EFS round-trips the write (20-50ms p99 cold).
// Hot paths log on every hook event, so the cumulative cost was real.
//
// Replaced with an in-process queue + a single fs.WriteStream-backed
// drainer running on the next tick. Public API stays the same — the
// console overrides below call enqueueLogLine() and return immediately;
// the line eventually lands on disk asynchronously.
//
// Backpressure: drops newest writes once the queue exceeds the cap
// (default 10k lines). Hitting that cap means EFS is so slow we'd
// rather lose recent log lines than OOM the container. Drops are
// counted and surfaced once per minute via stderr so operators can see.
//
// Rotation: rolls over when the date changes (UTC midnight) OR the
// current file exceeds MAX_FILE_BYTES. The rolled file is renamed to
// dredd-YYYY-MM-DD.<seq>.log so the active filename always sorts last
// for the day.
//
// Shutdown: SIGTERM in main() awaits flushLogs() before exiting so
// in-flight log lines reach disk.
const LOG_DIR = values["console-log-dir"]!;
try { mkdirSync(LOG_DIR, { recursive: true }); } catch {}

const MAX_QUEUE_LINES = 10_000;
const MAX_FILE_BYTES = 100 * 1024 * 1024; // 100 MB before forced rotation
const DROP_REPORT_INTERVAL_MS = 60_000;

let logQueue: string[] = [];
let logStream: ReturnType<typeof createWriteStream> | null = null;
let logStreamPath: string | null = null;
let logStreamBytes = 0;
let logDraining = false;
let droppedLines = 0;
let lastDropReport = 0;

function currentLogPath(): string {
  // Date in UTC so all containers in the fleet roll at the same instant.
  const date = new Date().toISOString().slice(0, 10);
  return join(LOG_DIR, `dredd-${date}.log`);
}

function ensureStream(): void {
  const desired = currentLogPath();
  // Date changed (midnight UTC) — rotate by closing and reopening.
  if (logStream && logStreamPath !== desired) {
    try { logStream.end(); } catch {}
    logStream = null;
    logStreamPath = null;
    logStreamBytes = 0;
  }
  // Size exceeded — rotate to dredd-YYYY-MM-DD.<n>.log so the active
  // file remains dredd-YYYY-MM-DD.log.
  if (logStream && logStreamBytes >= MAX_FILE_BYTES && logStreamPath) {
    try { logStream.end(); } catch {}
    let n = 1;
    while (existsSync(`${logStreamPath}.${n}`)) n++;
    try { renameSync(logStreamPath, `${logStreamPath}.${n}`); } catch {}
    logStream = null;
    logStreamBytes = 0;
  }
  if (!logStream) {
