function getDbConfig() {
  const databaseUrl = process.env.DATABASE_URL;
  if (!databaseUrl) {
    return null;
  }

  // Parse postgres://user:pass@host:port/dbname
  const match = databaseUrl.match(/postgres:\/\/([^:]+):([^@]+)@([^:]+):(\d+)\/(.+)/);
  if (!match) {
    return null;
  }

  return {
    host: match[3],
    port: parseInt(match[4], 10),
    database: match[5],
    user: match[1],
    password: match[2],
  };
}

