  if (!dbConfig) {
    // No database configured - return 503
    return res.status(503).json({ db: 'error', reason: 'no database configured' });
  }

  try {
    const pool = new Pool(dbConfig);
    const client = await pool.connect();

    // Execute a simple query to check DB connectivity
    await client.query('SELECT 1');

    client.release();
    await pool.end();

    res.status(200).json({ db: 'ok' });
